tinymce.PluginManager.add("custom-price-display-custom-mce-buttons",function(editor,url){window.custom_price_display_mce_data&&Object.keys(custom_price_display_mce_data.variables).forEach(function(buttonKey){custom_price_display_mce_data.editors.includes(editor.id)&&editor.addButton(buttonKey,{text:custom_price_display_mce_data.variables[buttonKey].name,tooltip:custom_price_display_mce_data.variables[buttonKey].description,icon:!1,onclick:function(){editor.insertContent(custom_price_display_mce_data.variables[buttonKey].variableKey)}})})});
